{
  "technical_and_design_decisions": [
    "Introduce a configurable ZooKeeper namespace (chroot) bound to tenant profile via application configuration.",
    "Implement Admin Server authentication using Spring Security with an interactive login form, removing plaintext credential files.",
    "Delete deprecated module registry download functions and clean up Shell and Admin-UI modules to use refactored APIs.",
    "For the xd-shell connectivity spike, design an abstraction that supports both a load balancer endpoint and a direct Admin Server/ZK address for experimental use.",
    "Upgrade the Kafka client to the 0.9 consumer rewrite and adapt the message bus implementation and tests to the new API.",
    "For Motion-JPEG ingest spike, specify a platform-independent approach (e.g., FFmpeg/JavaCV) instead of OpenCV, and produce a design spec.",
    "Add a boolean property 'message-rates-enabled' to servers.yml and conditionally render message rates in the Admin-UI cluster view.",
    "Create a separate maintenance branch (e.g., 1.0.x) for minor releases and configure CI accordingly."
  ],
  "assumptions": [
    "The codebase is an existing Spring-based distributed system with ZooKeeper, Admin Server, xd-shell, and module registry.",
    "A tenant profile concept already exists or can be added with minimal configuration.",
    "The developer is a single experienced engineer with a ready local dev environment (ZK, Kafka, build tools).",
    "Spikes U5 and U7 include only research and design deliverables, not full production implementation.",
    "Admin Server can be modified to support interactive authentication without major architectural changes.",
    "servers.yml is already used for cluster configuration and can accept new properties.",
    "Effort estimates are in work-hours and exclude external reviews, deployment, and elapsed time."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Create maintenance branch for minor releases",
      "activity_description": "Create a maintenance branch (e.g., 1.0.x) from the current release tag, configure CI/build for minor releases, and update versioning. Covers U3.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Configurable ZooKeeper namespace per tenant",
      "activity_description": "Design and implement support for a configurable ZK namespace/chroot based on tenant profile, refactor ZK client creation to use the namespace, and add unit/integration tests. Covers U1.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Interactive Admin Server authentication",
      "activity_description": "Implement interactive username/password authentication for Admin Server (e.g., Spring Security login), remove file-based credential storage, ensure passwords are not logged, and test. Covers U2.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Remove deprecated module registry functions and clean up modules",
      "activity_description": "Delete deprecated functions (e.g., module definition download), update callers, and clean up Shell and Admin-UI modules accordingly, with tests. Covers U4.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Spike: xd-shell to Admin Server connectivity",
      "activity_description": "Research and document approach for xd-shell to connect to random Tomcat port of Admin Server, evaluate direct ZK vs LB, and propose experimental mode. Produce spike report. Covers U5.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Upgrade Kafka consumer and fix tests",
      "activity_description": "Upgrade to Kafka 0.9 consumer rewrite, rerun failing message bus tests, refactor test code and message bus implementation as needed to pass. Covers U6.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Spike: Motion-JPEG streaming ingest feasibility",
      "activity_description": "Research feasibility of Motion-JPEG ingest for audio/video, evaluate alternatives to OpenCV for platform compatibility, and produce design specification. Covers U7.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Config parameter for message rates in cluster view",
      "activity_description": "Add boolean config property in servers.yml to enable/disable message rates, wire into Admin-UI cluster view, and test. Covers U8.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Integration testing, documentation, and delivery",
      "activity_description": "Perform cross-component integration testing of all changes, update user/developer documentation, and prepare the increment for merge/release.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 118
  }
}

